/* Advances the stream state at 0x1AECAC on every GameUpdate: opens it with SoundStreamIsReadComplete and
   starts it with SoundPlayIfNotPaused, then polls SoundIsPlayingUnlessMuted and marks it closed (-1)
   when it finishes. */
uint32_t MusicStreamUpdate(uint32_t ecx)
{
	uint32_t eax = 0;

	eax = ChatterLineState;
	if (eax == 0xFFFFFFFFu)
		return eax;
	if (eax != 0u)
	{
		if (eax == 1u)
		{
			eax = SoundIsPlayingUnlessMuted();
			if (eax == 0u)
				ChatterLineState = 0xFFFFFFFFu;
		}
		return eax;
	}
	SoundStreamIsReadComplete(&eax, &ecx);
	if (eax == 0u)
		return eax;
	eax = SoundPlayIfNotPaused();
	ChatterLineState = 1u;
	return eax;
}

