		esi = eax;
		if (esi != 0u)
		{
			eax = MEM32(esi + 0x44u);
			if (eax != GameObjectLastHandle)
			{
				handle = eax;
				GameObjectFromHandle(handle, &eax, &ignored_3, &ignored_2);
			}
			else
				eax = GameObjectLastObject;
			delay_ms = 0u;
			entity = eax;
			ai = esi;
			AIScheduleStateStart(esi, ai, entity, delay_ms, &ignored, &edi);
		}
