/* Counts and returns how many of the four pad ports give a nonzero result from vcPadIsOpen. */
uint32_t PadCountOpenPorts(void)
{
	uint32_t eax = 0, edi = 0, esi = 0, port = 0;

	edi = 0u;
	esi = 0u;
	do
	{
		port = esi;
		eax = vcPadIsOpen(port);
		if (eax != 0u)
			edi++;
		esi++;
	} while ((int32_t)esi < 4);
	eax = edi;
	return eax;
}

/* Returns the port index of the nth-th open pad, or 0xFFFFFFFF when fewer than nth of the four
   vcPadIsOpen ports are open. */
uint32_t PadGetNthOpenPort(uint32_t nth)
{
	uint32_t eax = 0, edi = 0, esi = 0, port = 0;

	edi = nth;
	if ((int32_t)edi >= 4)
	{
		eax = 0xFFFFFFFFu;
		return eax;
	}
	esi = 0u;
	for (;;)
	{
		port = esi;
		eax = vcPadIsOpen(port);
		if (eax != 0u)
		{
			edi--;
			if ((int32_t)edi <= 0)
				break;
		}
		esi++;
		if ((int32_t)esi >= 4)
		{
			eax = 0xFFFFFFFFu;
			return eax;
		}
	}
	eax = esi;
	return eax;
}

