			edx = g_esp + 0xCu;
			g_esp = g_esp - 4u;
			MEM32(g_esp) = edx;
			g_esp = g_esp - 4u;
			MEM32(g_esp) = 0u;
			g_esp = g_esp - 4u;
			MEM32(g_esp) = 0u;
			g_esp = g_esp - 4u;
			MEM32(g_esp) = 0xF00Au;
