/* In a two-player game compares each player's kill count from StatsGetValue against VersusKillLimit,
   sets VersusWinner to the player who reached the limit and clears the flag at 0x1B09B0, returning 1
   when the match is decided and 0 when both players are at the limit; with fewer than two players it
   returns 1 when ObjectHandleIsAlive on player 0's field at 0x44 returns 0. */
void VersusCheckMatchEnd(uint32_t *p_eax, uint32_t *p_ecx)
{
	uint32_t ecx = *p_ecx;
	uint32_t arg0 = 0, eax = 0, handle = 0, ignored = 0, ignored_2 = 0, object_handle = 0, stat_index = 0;
	uint32_t saved_eax = 0;

	if (PlayerCount >= 2)
	{
		stat_index = 0x41u;
		eax = StatsGetValue(stat_index);
		if ((int32_t)eax < VersusKillLimit)
		{
			stat_index = 0x42u;
			eax = StatsGetValue(stat_index);
			ecx = VersusKillLimit;
			if ((int32_t)eax < (int32_t)ecx)
			{
				eax = 0u;
				*p_eax = eax;
				*p_ecx = ecx;
				return;
			}
			eax = Players(1);
			VersusWinner = 1u;
			if (eax == 0u)
				eax = 0u;
			else if (eax != GameObjectLastHandle)
			{
				handle = eax;
				GameObjectFromHandle(handle, &eax, &ecx, &ignored);
				eax = MEM32(eax + 0x44u);
			}
			else
				eax = MEM32(GameObjectLastObject + 0x44u);
			saved_eax = eax;
			if ((eax & 0x3F800u) != 0xC000u)
			{
				arg0 = saved_eax;
				ecx = VeritechResetVelocity(ecx, arg0);
			}
			else
			{
				object_handle = saved_eax;
				ecx = GameObjectResetVelocity(ecx, object_handle);
			}
		}
		else
		{
			eax = Players(0);
			VersusWinner = 0u;
			if (eax == 0u)
				eax = 0u;
			else if (eax != GameObjectLastHandle)
			{
				handle = eax;
				GameObjectFromHandle(handle, &eax, &ignored_2, &ignored);
				eax = MEM32(eax + 0x44u);
			}
			else
				eax = MEM32(GameObjectLastObject + 0x44u);
			ecx = eax & 0x3F800u;
			saved_eax = eax;
			if (ecx != 0xC000u)
			{
				arg0 = saved_eax;
				ecx = VeritechResetVelocity(ecx, arg0);
				HUDVisible = 0u;
				eax = 1u;
				*p_eax = eax;
				*p_ecx = ecx;
				return;
			}
			object_handle = saved_eax;
			ecx = GameObjectResetVelocity(ecx, object_handle);
		}
		HUDVisible = 0u;
		eax = 1u;
		*p_eax = eax;
		*p_ecx = ecx;
		return;
	}
	eax = Players(0);
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ecx, &ignored);
	}
	else
		eax = GameObjectLastObject;
	arg0 = MEM32(eax + 0x44u);
	g_ecx = ecx;
	x86_call(ObjectHandleIsAlive, 0x00024BDFu, 1, arg0);
	eax = g_eax;
	ecx = g_ecx;
	ignored = g_edx;
	if (eax != 0u)
	{
		eax = 0u;
		*p_eax = eax;
		*p_ecx = ecx;
		return;
	}
	eax = 1u;
	*p_eax = eax;
	*p_ecx = ecx;
}

