/* Copies the versus score pairs 0x1E6834/0x1E6838, 0x1E682C/0x1E6830, 0x1E6824/0x1E6828 and
   0x1E681C/0x1E6820 into the four caller-provided pairs and returns the comparison of
   StatsGetValue(0x42) with StatsGetValue(0x41), reversed when 0x1E6818 is 1. */
uint32_t VersusResultGetScores(uint32_t arg0, uint32_t arg1, uint32_t arg2, uint32_t arg3)
{
	uint32_t negative = 0, overflow = 0;
	uint32_t eax = 0, esi = 0, stat_index = 0;

	eax = arg0;
	if (eax != 0u)
	{
		MEM32(eax) = PlayerShotsFired(0);
		MEM32(eax + 4u) = PlayerShotsFired(1);
	}
	eax = arg1;
	if (eax != 0u)
	{
		MEM32(eax) = PlayerShotsHit(0);
		MEM32(eax + 4u) = PlayerShotsHit(1);
	}
	eax = arg2;
	if (eax != 0u)
	{
		MEM32(eax) = PlayerMissilesFired(0);
		MEM32(eax + 4u) = PlayerMissilesFired(1);
	}
	eax = arg3;
	if (eax != 0u)
	{
		MEM32(eax) = PlayerMissilesHit(0);
		MEM32(eax + 4u) = PlayerMissilesHit(1);
	}
	eax = VersusSurprisePlayer;
	if (eax != 0u)
	{
		if (eax != 1u)
		{
			eax = 0u;
			return eax;
		}
		stat_index = 0x42u;
		eax = StatsGetValue(stat_index);
		stat_index = 0x41u;
		esi = eax;
		eax = StatsGetValue(stat_index);
		overflow = x86_overflow_sub32(eax, esi, 0u);
		negative = (eax - esi) >> 31;
		eax = negative ^ overflow;
		return eax;
	}
	stat_index = 0x42u;
	eax = StatsGetValue(stat_index);
	stat_index = 0x41u;
	esi = eax;
	eax = StatsGetValue(stat_index);
	overflow = x86_overflow_sub32(esi, eax, 0u);
	negative = (esi - eax) >> 31;
	eax = negative ^ overflow;
	return eax;
}

