/* Sets the text, the colour and the size of a player's HUD timer and whether it shows. */
void PlayerTimerSetText(uint32_t player_index, uint32_t text, uint32_t colour, uint32_t size, uint32_t visible, uint32_t *p_eax, uint32_t *p_ebx)
{
	uint32_t eax = 0, element_handle = 0, handle = 0, ignored = 0, ignored_2 = 0, text_buffer = 0;
	uint32_t saved_visible = 0, saved_size = 0, saved_colour = 0, saved_text = 0;

	saved_text = text;
	saved_colour = colour;
	saved_size = size;
	saved_visible = visible;
	eax = Players(player_index);
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	eax = MEM32(eax + 0x39Cu);
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	if (eax != 0u)
	{
		eax = MEM32(eax + 0x140u);
		if (eax == 0u)
		{
			*p_eax = eax;
			return;
		}
		element_handle = eax;
		text_buffer = saved_text;
		colour = saved_colour;
		size = saved_size;
		visible = saved_visible;
		*p_eax = eax;
		TimerElementSetText(element_handle, text_buffer, colour, size, visible, p_eax, p_ebx);
		return;
	}
	*p_eax = eax;
}

/* Shows or hides a player's HUD timer. */
void PlayerTimerSetVisible(uint32_t player, uint32_t visible)
{
	uint32_t eax = 0, element_handle = 0, handle = 0, ignored = 0, ignored_2 = 0;
	uint32_t saved_visible = 0;

	saved_visible = visible;
	eax = Players(player);
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	eax = MEM32(eax + 0x39Cu);
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	if (eax != 0u)
	{
		eax = MEM32(eax + 0x140u);
		if (eax != 0u)
		{
			element_handle = eax;
			visible = saved_visible;
			TimerElementSetVisible(element_handle, visible);
			return;
		}
	}
}

/* If the given pointer is non-null and its field at 0x140 is non-null, calls TimerElementSetVisible on
   that element with visible and returns its result. */
uint32_t GameObjectScreenElementSetVisible(uint32_t object, uint32_t visible)
{
	uint32_t element_handle = 0;

	if (object != 0u)
	{
		object = MEM32(object + 0x140u);
		if (object != 0u)
		{
			element_handle = object;
			return TimerElementSetVisible(element_handle, visible);
		}
	}
	return object;
}

