/* Returns 1 when the squared length of the vector at vector is less than the square of the float limit,
   else 0. */
uint32_t VectorSquaredLengthLessThanSquaredValue(uint32_t vector, uint32_t limit)
{
	uint32_t eax = 0, ebx = 0, ecx = 0;
	uint32_t stack = 0;
	double t1 = 0;

	ebx = vector;
	ecx = vector;
	t1 = x87_round(FLOAT_AT(ebx + 8u) * FLOAT_AT(ecx + 8u));
	stack = float_to_bits((float)x87_round(t1 + x87_round(x87_round(FLOAT_AT(ebx + 4u) * FLOAT_AT(ecx + 4u)) + x87_round(FLOAT_AT(ebx) * FLOAT_AT(ecx)))));
	if (!(x87_round(x87_float(limit) * x87_float(limit)) > x87_float(stack)))
	{
		eax = 0u;
		return eax;
	}
	eax = 1u;
	return eax;
}

