/* Whether two sides (an entity's +0x184, 1 and -1 the players') are enemies: 0 when they are the same,
   or when they are 0 and 1, else 1; EntityTakeDamage, EntityApplyRadiusEffect and the scene objects that
   react to a player use it. */
uint32_t SidesAreHostile(uint32_t arg0, uint32_t arg1)
{
	uint32_t zero = 0;
	uint32_t eax = 0, ecx = 0;

	eax = arg0;
	ecx = arg1;
	if (eax == ecx)
	{
		eax = 0u;
		return eax;
	}
	if (eax == 0u)
	{
		zero = ecx - 1u == 0u;
		if (zero)
		{
			eax = 0u;
			return eax;
		}
		eax = 1u;
		return eax;
	}
	if (eax != 1u)
	{
		eax = 1u;
		return eax;
	}
	zero = ecx == 0u;
	if (zero)
	{
		eax = 0u;
		return eax;
	}
	eax = 1u;
	return eax;
}

