/* When AICanStartActivity allows the transition it calls AISetActivity to apply state activity to the
   object and returns 1, otherwise it returns the check's result. */
uint32_t AIStartActivity(uint32_t ai, uint32_t activity)
{
	uint32_t eax = 0, edi = 0, esi = 0;

	esi = ai;
	if (esi == 0u)
	{
		eax = 0u;
		return eax;
	}
	edi = activity;
	activity = edi;
	ai = esi;
	eax = AICanStartActivity(ai, activity);
	if (eax != 0u)
	{
		activity = edi;
		ai = esi;
		AISetActivity(ai, activity);
		eax = 1u;
		return eax;
	}
	return eax;
}

