/* Sets the flag at offset 0x194 of the object in esi when vcPad_pressed_a or vcPad_pressed_start reports
   a press on the pad selected by the object's field at 0x18, or on any of the four pads when that field
   is negative. */
void PadConfirmFlagSet(uint32_t screen)
{
	uint32_t zero = 0;
	uint32_t eax = 0;

	DoNothing();
	if ((uint32_t)LoadingScreenFinished == 0u)
		return;
	eax = MEM32(screen + 0x18u);
	if ((int32_t)eax >= 0)
	{
		eax = eax * 0x210u;
		if (MEM32(eax + vcPad_pressed_a_VA(vcPads_VA)) != 0u)
		{
			MEM32(screen + 0x194u) = 1u;
			return;
		}
		zero = MEM32(eax + vcPad_pressed_start_VA(vcPads_VA)) == 0u;
		if (zero == 0u)
			MEM32(screen + 0x194u) = 1u;
		return;
	}
	if (vcPad_pressed_a(vcPads(0)) != 0u || vcPad_pressed_start(vcPads(0)) != 0u || vcPad_pressed_a(vcPads(1)) != 0u || vcPad_pressed_start(vcPads(1)) != 0u || vcPad_pressed_a(vcPads(2)) != 0u || vcPad_pressed_start(vcPads(2)) != 0u || vcPad_pressed_a(vcPads(3)) != 0u)
		MEM32(screen + 0x194u) = 1u;
	else
	{
		zero = vcPad_pressed_start(vcPads(3)) == 0u;
		if (zero == 0u)
		{
			MEM32(screen + 0x194u) = 1u;
			return;
		}
	}
}

