/* Maps key codes -4, -1, and 0x23 to slot indices 2, 0, and 1 and calls VeritechSetPackAll. */
uint32_t SlotSelectHandleKey(uint32_t ebp, uint32_t key)
{
	uint32_t eax = 0, pack = 0;

	eax = key;
	if (eax == 0xFFFFFFFCu)
	{
		pack = 2u;
		ebp = VeritechSetPackAll(pack, ebp);
		return ebp;
	}
	if (eax == 0xFFFFFFFFu)
	{
		pack = 0u;
		ebp = VeritechSetPackAll(pack, ebp);
		return ebp;
	}
	if (eax != 0x23u)
		return ebp;
	pack = 1u;
	ebp = VeritechSetPackAll(pack, ebp);
	return ebp;
}

