	{
		handle = ebx;
		GameObjectFromHandle(handle, p_eax, &ignored, p_edx);
		esi = *p_eax;
	}
	else
		esi = GameObjectLastObject;
	arg4 = 0u;
	arg3 = 0u;
	arg2 = ebx;
	arg1 = saved_sender_handle;
	arg0 = 0x2AF9u;
	g_edx = *p_edx;
