	eax = 0u;
	MEM32(edi + 0xD0u) = 0u;
	MEM32(edi + 0xE0u) = 0x3BA3D70Au;
	MEM32(edi + 0xECu) = 0x41F00000u;
	MEM32(edi + 0xE4u) = 0u;
	MEM32(edi + 0xDCu) = ebp;
	MEM32(edi + 0xF0u) = 0u;
	MEM32(edi + 0xF4u) = ebp;
	MEM32(edi + 0xE8u) = 0u;
	MEM32(edi + 0xF8u) = vcGameTime;
	MEM32(edi + 0x100u) = 0u;
	MEM32(edi + 0x104u) = 0x41200000u;
	MEM32(edi + 0x108u) = 0u;
	if (MEM32(data + 0x74u) != ebp)
	{
		MEM32(edi + 0xFCu) = eax;
		PathRefreshNodeObjects(ebp, &eax, &ebx, &edi);
		return eax;
	}
	MEM32(edi + 0xFCu) = MEM32(edi + 0xFCu) | ebp;
	MEM32(edi + 0x7Cu) = eax;
	MEM32(edi + 0x80u) = eax;
	MEM32(edi + 0x84u) = eax;
	MEM32(edi + 0x100u) = MEM32(data + 0x78u);
