/* Checks the entity's flags and message type, calls EntityTakeDamage, and on a successful hit sets
   hit-reaction fields and calls VeritechSetPack when health is depleted. */
uint32_t EntityDamageHandler(uint32_t attacker_handle, uint32_t data, uint32_t entry, uint32_t ebp, uint32_t victim, uint32_t entity_handle)
{
	uint32_t arg0 = 0, arg1 = 0, damage = 0, entity = 0, handle = 0, ignored = 0;
	double f0 = 0, t1 = 0;

	if ((MEM8(victim + 4u) & 0x40u) != 0u && (attacker_handle & 0x7C0000u) == 0x80000u)
	{
		attacker_handle = ((int32_t)attacker_handle >> 11) & 0x7Fu;
		if (attacker_handle == 0x49u || attacker_handle == 0x48u)
			return attacker_handle;
	}
	damage = data;
	entity = victim;
	handle = entity_handle;
	EntityTakeDamage(handle, entity, damage, &attacker_handle, &ignored, &entry, &ebp, &victim, &entity_handle);
	if (attacker_handle != 0u)
	{
		attacker_handle = MEM32(entry + 0x10u) | 1u;
		MEM16(entry + 0xEu) = 0xEu;
		MEM32(entry + 0x10u) = attacker_handle;
		return attacker_handle;
	}
	f0 = FLOAT_AT(victim + 0x17Cu);
	t1 = 0.0f;
	attacker_handle = (attacker_handle & ~0xFFFFu) | (uint16_t)x87_status(f0, t1, 0u);
	if (f0 <= t1)
	{
		attacker_handle = MEM32(victim + 0x180u);
		if (attacker_handle != 0u)
		{
			arg1 = 0u;
			arg0 = entity_handle;
			VeritechSetPack(arg0, arg1, &attacker_handle, &entry, &ebp, &victim, &entity_handle);
		}
	}
	return attacker_handle;
}

