/* Whether a veritech of VeritechChoices can be chosen: its requirements met (VeritechRequirementMet),
   the armored ones (whose second is -4) only in a versus arena (a level past 58); the female power
   armour, the 16th, once award 16 is won and in a versus arena. */
uint32_t VeritechChoiceIsOpen(uint32_t choice)
{
	uint32_t award = 0, eax = 0, esi = 0, requirement = 0;

	esi = choice;
	if (esi == 0xFu)
	{
		award = 0x10u;
		eax = AwardRank(award);
		if ((int16_t)eax > 0)
		{
			eax = LevelGetCurrent();
			if ((int32_t)eax >= 0x3B)
			{
				choice = 1u;
				return choice;
			}
		}
		choice = 0u;
		return choice;
	}
	esi = esi << 4;
	if (MEM32(esi + VeritechChoice_requires_also_VA(VeritechChoices_VA)) == 0xFFFFFFFFu)
	{
		requirement = MEM32(esi + VeritechChoice_requires_VA(VeritechChoices_VA));
		eax = VeritechRequirementMet(requirement);
		return eax;
	}
	eax = LevelGetCurrent();
	if ((int32_t)eax >= 0x3B || MEM32(esi + VeritechChoice_requires_also_VA(VeritechChoices_VA)) != 0xFFFFFFFCu)
	{
		requirement = MEM32(esi + VeritechChoice_requires_also_VA(VeritechChoices_VA));
		eax = VeritechRequirementMet(requirement);
		if (eax == 0u)
		{
			choice = 0u;
			return choice;
		}
		requirement = MEM32(esi + VeritechChoice_requires_VA(VeritechChoices_VA));
		eax = VeritechRequirementMet(requirement);
		if (eax == 0u)
		{
			choice = 0u;
			return choice;
		}
		choice = 1u;
		return choice;
	}
	choice = 0u;
	return choice;
}

/* Returns nonzero when the VeritechChoice at index edi satisfies its VeritechChoice_requires_VA and
   VeritechChoice_requires_also_VA requirements via VeritechRequirementMet, and unless the index is 4 or
   0xF also requires the LevelGet of LevelGetCurrent to have bit 0x40 set or the current level index to
   be at least 0x3B. */
uint32_t VeritechChoiceIsAvailable(uint32_t index)
{
	uint32_t eax = 0, esi = 0, level = 0, requirement = 0;

	esi = index << 4;
	eax = MEM32(esi + VeritechChoice_requires_also_VA(VeritechChoices_VA));
	if (eax == 0xFFFFFFFFu)
	{
		requirement = MEM32(esi + VeritechChoice_requires_VA(VeritechChoices_VA));
		eax = VeritechRequirementMet(requirement);
		if (eax != 0u)
		{
			if ((int32_t)index <= 4 || index == 0xFu)
				return eax;
			eax = LevelGetCurrent();
			level = eax;
			eax = LevelGet(level);
			if ((MEM8(eax) & 0x40u) == 0u)
			{
				eax = LevelGetCurrent();
				if ((int32_t)eax < 0x3B)
				{
					eax = 0u;
					return eax;
				}
			}
			eax = 1u;
		}
		return eax;
	}
	requirement = eax;
	eax = VeritechRequirementMet(requirement);
	if (eax == 0u)
	{
		eax = 0u;
		return eax;
	}
	requirement = MEM32(esi + VeritechChoice_requires_VA(VeritechChoices_VA));
	eax = VeritechRequirementMet(requirement);
	if (eax == 0u)
	{
		eax = 0u;
		return eax;
	}
	eax = 1u;
	if ((int32_t)index <= 4 || index == 0xFu)
		return eax;
	eax = LevelGetCurrent();
	level = eax;
	eax = LevelGet(level);
	if ((MEM8(eax) & 0x40u) == 0u)
	{
		eax = LevelGetCurrent();
		if ((int32_t)eax < 0x3B)
		{
			eax = 0u;
			return eax;
		}
	}
	eax = 1u;
	return eax;
}

/* Whether a paint design can be chosen: in the training (chapter 5) only the first, Trainer; otherwise
   every one under MISSMACROSS's cheat (Cheats' 0x80), or one earned. */
uint32_t PaintDesignIsOpen(uint32_t design)
{
	uint32_t zero = 0;
	uint32_t design_2 = 0, eax = 0, level = 0, mask = 0;

	eax = LevelGetCurrent();
	level = eax;
	eax = LevelGet(level);
	if (MEM32(eax + 0x50u) == 5u)
	{
		zero = design == 0u;
		eax = zero;
		return eax;
	}
	mask = 0x80u;
	eax = CheatIsOn(mask);
	if (eax == 0u)
	{
		design_2 = design;
		eax = PaintDesignIsEarned(design_2);
		if (eax == 0u)
			return eax;
	}
	eax = 1u;
	return eax;
}

