/* Registers the VF1SX type (Entity 29), its asset VF-1SX: a player's; with two players VF1SM in its
   place (Entity 56 and 57, with Roy's skin, have the asset too): fills its GameObjectType and stores it
   in its family. */
void VF1SX_Register(uint32_t family)
{
	uint32_t arg0 = 0;

	GameObjectType_size(VF1SXType_VA) = 0x308u;
	GameObjectType_startup(VF1SXType_VA) = 0x5C2B0u;
	GameObjectType_shutdown(VF1SXType_VA) = 0x5C2E0u;
	GameObjectType_state_machine(VF1SXType_VA) = 0x484B0u;
	GameObjectType_load(VF1SXType_VA) = 0x19500u;
	GameObjectType_collect(VF1SXType_VA) = 0x196A0u;
	GameObjectType_version(VF1SXType_VA) = 0u;
	GameObjectType_flags(VF1SXType_VA) = 1u;
	MEM32(family + 0x84u) = VF1SXType_VA;
	arg0 = VF1SXVeritechModel_VA;
	VeritechConstantsInit(arg0);
}

/* Returns the address 0x1FC338 of the block that VF1JX's registering function fills with its model and
   pointers to its constants; its state machine clones the model from it. */
uint32_t VF1JXConstantsGet(void)
{
	uint32_t eax = 0;

	eax = VF1JXVeritechModel_VA;
	return eax;
}

/* The VF1JX type's first use (GameObjectTypeUse): gets what its objects share. */
uint32_t VF1JX_Startup(uint32_t ebx, uint32_t ebp, uint32_t esi, uint32_t edi)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, eax = 0, ignored = 0, ignored_2 = 0;

	arg0 = VF1JXText_VA;
	ObjectCreateInstanceFromName(arg0, &eax, &ebx, &ebp);
	arg2 = 0u;
	arg1 = 0x14u;
	arg0 = eax;
	VeritechModel_model(VF1JXVeritechModel_VA) = eax;
	x86_call(vcSceneObjectChangeFlags_entry, 0x0005E1A9u, 3, arg0, arg1, arg2);
	ignored = g_eax;
	ignored_2 = g_edx;
	arg0 = VF1JXVeritechModel_VA;
	eax = VeritechModelLoad(ebx, ebp, esi, edi, arg0);
	return eax;
}

/* The VF1JX type's last release (GameObjectTypeRelease): lets go of what its objects share. */
uint32_t VF1JX_Shutdown(void)
{
	uint32_t arg0 = 0, eax = 0, ignored = 0, ignored_2 = 0, ignored_3 = 0;

	arg0 = VeritechModel_model(VF1JXVeritechModel_VA);
	x86_call(vcObjectRelease_entry, 0x0005E1CBu, 1, arg0);
	ignored = g_eax;
	ignored_2 = g_ecx;
	ignored_3 = g_edx;
	arg0 = VF1JXVeritechModel_VA;
	eax = VF1Shutdown(arg0);
	return eax;
}

