/* Registers the VF1JX type (Entity 28), its asset VF-1JX: fills its GameObjectType and stores it in its
   family. */
void VF1JX_Register(uint32_t family)
{
	uint32_t arg0 = 0;

	GameObjectType_size(VF1JXType_VA) = 0x308u;
	GameObjectType_startup(VF1JXType_VA) = 0x5E190u;
	GameObjectType_shutdown(VF1JXType_VA) = 0x5E1C0u;
	GameObjectType_state_machine(VF1JXType_VA) = 0x484B0u;
	GameObjectType_load(VF1JXType_VA) = 0x19500u;
	GameObjectType_collect(VF1JXType_VA) = 0x196A0u;
	GameObjectType_version(VF1JXType_VA) = 0u;
	GameObjectType_flags(VF1JXType_VA) = 1u;
	MEM32(family + 0x80u) = VF1JXType_VA;
	arg0 = VF1JXVeritechModel_VA;
	VeritechFormConstantsInit(arg0);
}

/* Returns the address 0x1FDAE8 of the block that VF1BX's registering function fills with its model and
   pointers to its constants; its state machine clones the model from it. */
uint32_t VF1BXConstantsGet(void)
{
	uint32_t eax = 0;

	eax = VF1BXVeritechModel_VA;
	return eax;
}

/* The VF1BX type's first use (GameObjectTypeUse): gets what its objects share. */
uint32_t VF1BX_Startup(uint32_t ebx, uint32_t ebp, uint32_t esi, uint32_t edi)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, eax = 0, ignored = 0, ignored_2 = 0;

	arg0 = VF1BXText_VA;
	ObjectCreateInstanceFromName(arg0, &eax, &ebx, &ebp);
	arg2 = 0u;
	arg1 = 0x14u;
	arg0 = eax;
	VeritechModel_model(VF1BXVeritechModel_VA) = eax;
	x86_call(vcSceneObjectChangeFlags_entry, 0x00060089u, 3, arg0, arg1, arg2);
	ignored = g_eax;
	ignored_2 = g_edx;
	arg0 = VF1BXVeritechModel_VA;
	eax = VeritechModelLoad(ebx, ebp, esi, edi, arg0);
	return eax;
}

/* The VF1BX type's last release (GameObjectTypeRelease): lets go of what its objects share. */
uint32_t VF1BX_Shutdown(void)
{
	uint32_t arg0 = 0, eax = 0, ignored = 0, ignored_2 = 0, ignored_3 = 0;

	arg0 = VeritechModel_model(VF1BXVeritechModel_VA);
	x86_call(vcObjectRelease_entry, 0x000600ABu, 1, arg0);
	ignored = g_eax;
	ignored_2 = g_ecx;
	ignored_3 = g_edx;
	arg0 = VF1BXVeritechModel_VA;
	eax = VF1Shutdown(arg0);
	return eax;
}

