/* Depending on the mode stored at +0x28C, enables weapon slot 0 or slots 1 and 2 through
   EntityPartSetEnabled. */
uint32_t UnitApplyWeaponSlots(uint32_t entity, uint32_t esi)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, eax = 0, ignored = 0;
	uint32_t t1 = 0, t2 = 0;

	t1 = MEM32(entity + 0x28Cu);
	eax = t1;
	if (t1 == 0u)
	{
		arg2 = 1u;
		arg1 = 0u;
		arg0 = MEM32(esi + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &eax, &esi);
		return eax;
	}
	t2 = eax;
	eax = t2 - 1u;
	if (t2 != 1u)
		return eax;
	arg2 = 1u;
	arg1 = 1u;
	arg0 = MEM32(esi + 0x194u);
	EntityPartSetEnabled(arg0, arg1, arg2, &ignored, &esi);
	arg2 = 1u;
	arg1 = 2u;
	arg0 = MEM32(esi + 0x194u);
	EntityPartSetEnabled(arg0, arg1, arg2, &eax, &esi);
	return eax;
}

/* If bit 0x100 of the unit's flags is set, clears it and disables all three weapon slots with
   EntityPartSetEnabled. */
uint32_t UnitDisableWeaponSlots(uint32_t entity)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, eax = 0, ignored = 0;

	eax = MEM32(entity + 4u);
	if (((eax >> 8) & 1u) != 0u)
	{
		arg2 = 0u;
		MEM32(entity + 4u) = eax & ~0x100u;
		arg1 = 0u;
		arg0 = MEM32(entity + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &ignored, &entity);
		arg2 = 0u;
		arg1 = 1u;
		arg0 = MEM32(entity + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &ignored, &entity);
		arg2 = 0u;
		arg1 = 2u;
		arg0 = MEM32(entity + 0x194u);
		EntityPartSetEnabled(arg0, arg1, arg2, &eax, &entity);
	}
	return eax;
}

