	uint32_t eax = 0, ebp = 0, ebx = 0, ecx = 0, edi = 0, esi = 0, handle = 0, ignored = 0, ignored_2 = 0;
	uint32_t saved_eax = 0, stack = 0, saved_arg0 = 0;
