/* Scans levels 0 through 0x31 calling LevelIsOpen and LevelIsFinished and returns the first level that
   is open and not finished, or 0 if none is. */
uint32_t LevelFindFirstOpenUnfinished(void)
{
	uint32_t eax = 0, esi = 0, level = 0;

	esi = 0u;
	for (;;)
	{
		level = esi;
		eax = LevelIsOpen(level);
		if (eax != 0u)
		{
			level = esi;
			eax = LevelIsFinished(level);
			if (eax == 0u)
				break;
		}
		esi++;
		if ((int32_t)esi >= 0x32)
		{
			eax = 0u;
			return eax;
		}
	}
	eax = esi;
	return eax;
}

