						break;
					case 0x0A6A45u:
						f0_2 = x87_round(FLOAT_AT(MEM32(MEM32(esi_2) + 0x10u)) * 0.9f);
						break;
					case 0x0A6A54u:
						f0_2 = x87_round(FLOAT_AT(MEM32(MEM32(esi_2) + 0x10u)) * 0.3f);
						break;
					case 0x0A6A63u:
