	stack_8 = float_to_bits((float)(double)(int32_t)MEM32(esi + 0x104u));
	arg0 = float_to_bits((float)(double)(int32_t)MEM32(esi + 0x118u));
	eax = x86_call(vcTextSetSize_entry, 0x000AC9B5u, 1, arg0);
	x87_pop();
