	{
		arg0 = esi;
		x86_call(vcTextWidth_entry, 0x000AC9CAu, 1, arg0);
		*p_ecx = g_ecx;
		f0 = x87_pop();
		stack = float_to_bits((float)x87_round(x87_float(stack) - x87_round(f0 * 0.5)));
	}
