/* Reads pad input (vcPad_pressed_b/vcPad_pressed_back) for the difficulty screen, sends message 0x32CB
   through GameObjectSendMessage, sets the closed flag at +0x128 and reads the chosen value with
   GameObjectGetDifficulty into Difficulty via GameObjectSetSelectionIndex, asking MenuCancelSoundAsked
   on cancel. */
void DifficultyScreenUpdate(uint32_t screen_handle, uint32_t screen)
{
	uint32_t zero = 0;
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, arg3 = 0, arg4 = 0, eax = 0, edi = 0, ignored = 0, ignored_2 = 0, ignored_3 = 0, ignored_4 = 0, index = 0, object_handle = 0;

	edi = screen_handle;
	DoNothing();
	eax = MEM32(screen + 0x124u);
	if (eax == 0u)
		return;
	arg4 = 0u;
	arg3 = 0u;
	arg2 = eax;
	arg1 = edi;
	arg0 = 0x32CBu;
	x86_call(GameObjectSendMessage, 0x000B065Au, 5, arg0, arg1, arg2, arg3, arg4);
	object_handle = MEM32(screen + 0x124u);
	GameObjectGetDifficulty(object_handle, &eax, &ignored);
	edi = 1u;
	if (eax != 0xFFFFFFFFu)
	{
		object_handle = MEM32(screen + 0x124u);
		MEM32(screen + 0x12Cu) = edi;
		GameObjectGetDifficulty(object_handle, &eax, &ignored);
		Difficulty = eax;
	}
	eax = MEM32(screen + 0x18u);
	if ((int32_t)eax >= 0)
	{
		eax = eax * 0x210u;
		if (MEM32(eax + vcPad_pressed_b_VA(vcPads_VA)) != 0u)
		{
			eax = MEM32(screen + 0x124u);
			MEM32(screen + 0x128u) = edi;
			index = Difficulty;
			object_handle = eax;
			GameObjectSetSelectionIndex(object_handle, index, &ignored_2, &ignored_3, &ignored_4);
			MenuCancelSoundAsked = edi;
			return;
		}
		zero = MEM32(eax + vcPad_pressed_back_VA(vcPads_VA)) == 0u;
		if (zero == 0u)
		{
			eax = MEM32(screen + 0x124u);
			MEM32(screen + 0x128u) = edi;
			index = Difficulty;
			object_handle = eax;
			GameObjectSetSelectionIndex(object_handle, index, &ignored_2, &ignored_3, &ignored_4);
			MenuCancelSoundAsked = edi;
		}
		return;
	}
	if (vcPad_pressed_b(vcPads(0)) != 0u || vcPad_pressed_back(vcPads(0)) != 0u || vcPad_pressed_b(vcPads(1)) != 0u || vcPad_pressed_back(vcPads(1)) != 0u || vcPad_pressed_b(vcPads(2)) != 0u || vcPad_pressed_back(vcPads(2)) != 0u || vcPad_pressed_b(vcPads(3)) != 0u)
	{
		eax = MEM32(screen + 0x124u);
		MEM32(screen + 0x128u) = edi;
		index = Difficulty;
		object_handle = eax;
		GameObjectSetSelectionIndex(object_handle, index, &ignored_2, &ignored_3, &ignored_4);
		MenuCancelSoundAsked = edi;
	}
	else
	{
		zero = vcPad_pressed_back(vcPads(3)) == 0u;
		if (zero == 0u)
		{
			eax = MEM32(screen + 0x124u);
			MEM32(screen + 0x128u) = edi;
			index = Difficulty;
			object_handle = eax;
			GameObjectSetSelectionIndex(object_handle, index, &ignored_2, &ignored_3, &ignored_4);
			MenuCancelSoundAsked = edi;
			return;
		}
	}
}

/* The DifficultyScreen type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t DifficultyScreen_StateMachine(uint32_t ebx, uint32_t ebp, uint32_t esi, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, arg3 = 0, arg4 = 0, eax = 0, ecx = 0, edi = 0, edx = 0, esi_2 = 0, handle = 0, ignored = 0, ignored_2 = 0, ignored_3 = 0, screen = 0, screen_2 = 0, screen_handle = 0, screen_handle_2 = 0, start = 0;
	uint32_t saved_object = 0;

	saved_object = object;
	ecx = entry;
	eax = message;
	edx = MEM32(eax + 4u);
	edi = MEM32(ecx);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax == 0x32CAu)
		{
			eax = MEM32(object + 0x124u);
			if (eax != 0u)
			{
				arg4 = 0u;
				arg3 = 0u;
				arg2 = eax;
				arg1 = edi;
				arg0 = 0x32CAu;
				x86_call(GameObjectSendMessage, 0x000B07A2u, 5, arg0, arg1, arg2, arg3, arg4);
			}
			screen_2 = edi;
			arg1 = 0u;
			arg2 = 0u;
			arg3 = 0u;
			ScreenDrawElements(screen_2, arg1, arg2, arg3, &ignored, &ebx, &esi, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32CBu)
		{
			screen = object;
			screen_handle = edi;
			DifficultyScreenUpdate(screen_handle, screen);
			eax = 1u;
			return eax;
		}
		if (eax != 0xFFFAu)
		{
			eax = 0u;
			return eax;
		}
		screen_2 = edi;
		ScreenDestroyElements(screen_2, &ignored, &edx);
		eax = MEM32(saved_object + 0x124u);
		if (eax != 0u)
		{
			handle = eax;
			GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
		}
		eax = 1u;
		return eax;
	}
	esi_2 = object;
	edx = data;
	start = edx;
	screen_handle_2 = edi;
	arg0 = ecx;
	DifficultyScreenCreate(edx, ebx, ebp, esi_2, edi, arg0, screen_handle_2, start);
	eax = 1u;
	return eax;
}

