/* The MedalsScreen type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t MedalsScreen_StateMachine(uint32_t ebp, uint32_t esi, uint32_t edi, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data, uint32_t time)
{
	uint32_t arg0 = 0, eax = 0, ebx = 0, ecx = 0, edx = 0, esi_2 = 0, ignored = 0, object_handle = 0, screen = 0, screen_handle = 0, start = 0;

	ecx = entry;
	eax = message;
	edx = MEM32(eax + 4u);
	ebx = MEM32(ecx);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C8u)
		{
			object_handle = ebx;
			GameObjectSendMessageToVisibleChildren(ebx, esi, object_handle, &ignored, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C9u)
		{
			arg0 = ebx;
			GameObjectBroadcastToVisibleChildren(arg0, &ignored, &ebx, &esi, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32CAu)
		{
			esi_2 = object;
			eax = ebx;
			MedalsScreenDrawHud(eax, ebx, esi_2, edi);
			eax = 1u;
			return eax;
		}
		if (eax != 0xFFFAu)
		{
			eax = 0u;
			return eax;
		}
		edx = time;
		screen = object;
		screen_handle = ebx;
		MedalsScreenCleanup(screen_handle, screen, edx);
		eax = 1u;
		return eax;
	}
	esi_2 = object;
	start = data;
	entry = ecx;
	MedalsScreenInit(start, edx, ebx, ebp, esi_2, edi, entry);
	eax = 1u;
	return eax;
}

