/* On A/Start or down/left-y pad input from any pad, calls ScreenSetActive on edi and on the object at
   esi+0x20. */
void ObjectivesScreenReadPad(uint32_t screen, uint32_t screen_handle)
{
	uint32_t active = 0, eax = 0, ecx = 0, screen_2 = 0;

	DoNothing();
	eax = MEM32(screen + 0x18u);
	if ((int32_t)eax < 0)
	{
		if (vcPad_pressed_a(vcPads(0)) != 0u || vcPad_pressed_start(vcPads(0)) != 0u || vcPad_pressed_a(vcPads(1)) != 0u || vcPad_pressed_start(vcPads(1)) != 0u || vcPad_pressed_a(vcPads(2)) != 0u || vcPad_pressed_start(vcPads(2)) != 0u || vcPad_pressed_a(vcPads(3)) != 0u || vcPad_pressed_start(vcPads(3)) != 0u)
		{
			active = 0u;
			screen_2 = screen_handle;
			ScreenSetActive(screen_2, active);
			active = 1u;
			screen_2 = MEM32(screen + 0x20u);
			ScreenSetActive(screen_2, active);
			return;
		}
	}
	else
	{
		ecx = eax * 0x210u;
		if (MEM32(ecx + vcPad_pressed_a_VA(vcPads_VA)) != 0u || MEM32(ecx + vcPad_pressed_start_VA(vcPads_VA)) != 0u)
		{
			active = 0u;
			screen_2 = screen_handle;
			ScreenSetActive(screen_2, active);
			active = 1u;
			screen_2 = MEM32(screen + 0x20u);
			ScreenSetActive(screen_2, active);
			return;
		}
	}
	if ((int32_t)eax < 0)
	{
		if (vcPad_pressed_down(vcPads(0)) != 0u || (vcPad_pressed_left_y(vcPads(0)) != 0u && (double)vcPad_left_y(vcPads(0)) < 0.0f) || vcPad_pressed_down(vcPads(1)) != 0u || (vcPad_pressed_left_y(vcPads(1)) != 0u && (double)vcPad_left_y(vcPads(1)) < 0.0f) || vcPad_pressed_down(vcPads(2)) != 0u || (vcPad_pressed_left_y(vcPads(2)) != 0u && (double)vcPad_left_y(vcPads(2)) < 0.0f) || vcPad_pressed_down(vcPads(3)) != 0u || (vcPad_pressed_left_y(vcPads(3)) != 0u && (double)vcPad_left_y(vcPads(3)) < 0.0f))
		{
			active = 0u;
			screen_2 = screen_handle;
			ScreenSetActive(screen_2, active);
			active = 1u;
			screen_2 = MEM32(screen + 0x20u);
			ScreenSetActive(screen_2, active);
			return;
		}
		return;
	}
	eax = eax * 0x210u;
	if (MEM32(eax + vcPad_pressed_down_VA(vcPads_VA)) != 0u)
	{
		active = 0u;
		screen_2 = screen_handle;
		ScreenSetActive(screen_2, active);
		active = 1u;
		screen_2 = MEM32(screen + 0x20u);
		ScreenSetActive(screen_2, active);
		return;
	}
	if (MEM32(eax + vcPad_pressed_left_y_VA(vcPads_VA)) == 0u)
		return;
	if (!(FLOAT_AT(eax + vcPad_left_y_VA(vcPads_VA)) < 0.0f))
		return;
	active = 0u;
	screen_2 = screen_handle;
	ScreenSetActive(screen_2, active);
	active = 1u;
	screen_2 = MEM32(screen + 0x20u);
	ScreenSetActive(screen_2, active);
}

/* The ObjectivesScreen type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t ObjectivesScreen_StateMachine(uint32_t ebx, uint32_t ebp, uint32_t esi, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data)
{
	uint32_t arg0 = 0, eax = 0, ebx_2 = 0, ecx = 0, edi = 0, edx = 0, ignored = 0, object_handle = 0, screen = 0, screen_2 = 0, screen_3 = 0, screen_handle = 0, start = 0;

	ecx = entry;
	eax = message;
	edx = MEM32(eax + 4u);
	edi = MEM32(ecx);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C8u)
		{
			object_handle = edi;
			GameObjectSendMessageToVisibleChildren(ebx, esi, object_handle, &ignored, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C9u)
		{
			arg0 = edi;
			GameObjectBroadcastToVisibleChildren(arg0, &ignored, &ebx, &esi, &edi);
			eax = 1u;
			return eax;
		}
		if (eax != 0x32CAu)
		{
			if (eax == 0x32CBu)
			{
				screen_3 = object;
				ObjectivesScreenReadPad(screen_3, edi);
				eax = 1u;
				return eax;
			}
			if (eax != 0xFFFAu)
			{
				eax = 0u;
				return eax;
			}
			screen_2 = edi;
			ScreenDestroyElements(screen_2, &ignored, &edx);
			eax = 1u;
			return eax;
		}
		screen = object;
		screen_handle = edi;
		arg0 = ecx;
		ScreenDrawListEntries(screen, ebx, ebp, esi, edi, arg0, screen_handle);
		eax = 1u;
		return eax;
	}
	ebx_2 = object;
	start = data;
	screen_handle = edi;
	arg0 = ecx;
	ObjectivesScreenBuildElements(start, edx, ebx_2, ebp, esi, edi, arg0, screen_handle);
	eax = 1u;
	return eax;
}

