/* Destroys the game objects held in the screen's handle fields and the global at 0x21CBB8 with
   GameObjectDestroy and resets 0x1B09B0 when 0x1BC760 is clear. */
void PauseScreenDestroyObjects(uint32_t screen, uint32_t edx, uint32_t screen_handle)
{
	uint32_t eax = 0, edi = 0, esi = 0, handle = 0, ignored = 0, ignored_2 = 0, ignored_3 = 0, screen_2 = 0;
	uint32_t t1 = 0;

	esi = screen;
	if (CinemaPlaying == 0u)
		HUDVisible = 1u;
	screen_2 = screen_handle;
	ScreenDestroyElements(screen_2, &ignored, &edx);
	eax = PauseMenuListHandle;
	if (eax != 0u)
	{
		handle = eax;
		GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
		PauseMenuListHandle = 0u;
	}
	eax = MEM32(esi + 0x124u);
	if (eax != 0u)
	{
		handle = eax;
		GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
	}
	eax = MEM32(esi + 0x168u);
	if (eax != 0u)
	{
		handle = eax;
		GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
	}
	eax = MEM32(esi + 0x16Cu);
	if (eax != 0u)
	{
		handle = eax;
		GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
	}
	esi += 0x15Cu;
	edi = 3u;
	do
	{
		eax = MEM32(esi - 0xCu);
		if (eax != 0u)
		{
			handle = eax;
			GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
		}
		eax = MEM32(esi);
		if (eax != 0u)
		{
			handle = eax;
			GameObjectDestroy(handle, &ignored, &ignored_2, &ignored_3);
		}
		esi += 4u;
		t1 = edi;
		edi = t1 - 1u;
	} while (t1 != 1u);
}

