/* The PauseScreen type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t PauseScreen_StateMachine(uint32_t ebx, uint32_t ebp, uint32_t esi, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data, uint32_t time)
{
	uint32_t arg0 = 0, eax = 0, ebx_2 = 0, ecx = 0, edi = 0, edx = 0, ignored = 0, object_handle = 0, screen = 0, screen_2 = 0, screen_handle = 0;

	eax = message;
	edx = MEM32(eax + 4u);
	edi = MEM32(entry);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C8u)
		{
			object_handle = edi;
			GameObjectSendMessageToVisibleChildren(ebx, esi, object_handle, &ignored, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32C9u)
		{
			arg0 = edi;
			GameObjectBroadcastToVisibleChildren(arg0, &ignored, &ebx, &esi, &edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32CAu)
		{
			screen_2 = object;
			PauseScreenDrawSprites(ebx, screen_2, edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0x32CBu)
		{
			eax = object;
			ecx = edi;
			PauseScreenReadPad(eax, ecx, ebp, edi);
			eax = 1u;
			return eax;
		}
		if (eax == 0xF00Au)
		{
			eax = 1u;
			return eax;
		}
		if (eax != 0xFFFAu)
		{
			eax = 0u;
			return eax;
		}
		edx = time;
		screen = object;
		screen_handle = edi;
		PauseScreenDestroyObjects(screen, edx, screen_handle);
		eax = 1u;
		return eax;
	}
	eax = data;
	ecx = object;
	ebx_2 = edi;
	PauseScreenInit(eax, ecx, edx, ebx_2, ebp, esi, edi);
	eax = 1u;
	return eax;
}

