	MEM32(g_esp) = edx;
	g_esp = g_esp - 4u;
	MEM32(g_esp) = ecx;
	g_esp = g_esp - 4u;
	MEM32(g_esp) = ebp_2;
	g_esp = g_esp - 4u;
	MEM32(g_esp) = weapon;
	weapon_2 = MEM32(g_esp);
	time_2 = MEM32(g_esp + 4u);
	ammo = MEM32(g_esp + 8u);
	cost = MEM32(g_esp + 0xCu);
	eax = WeaponFireCheck(weapon_2, time_2, ammo, cost);
