/* The FlareWeapon type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t FlareWeapon_StateMachine(uint32_t ebp, uint32_t edi, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data, uint32_t time)
{
	uint32_t arg0 = 0, arg1 = 0, eax = 0, ecx = 0, edx = 0, shot = 0, time_2 = 0, weapon = 0;

	ecx = entry;
	eax = message;
	edx = MEM32(ecx);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		MEM32(object) = FlareWeaponSpec_VA;
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax != 0x3E8u)
		{
			eax = 0u;
			return eax;
		}
		shot = data;
		weapon = object;
		time_2 = time;
		arg1 = edx;
		arg0 = ecx;
		FlareWeaponFire(shot, ebp, weapon, edi, arg0, arg1, time_2);
		eax = 1u;
		return eax;
	}
	eax = data;
	ecx = object;
	MEM32(ecx + 4u) = MEM32(eax);
	MEM32(ecx + 8u) = MEM32(eax + 4u);
	MEM32(ecx + 0xCu) = MEM32(eax + 8u);
	MEM32(ecx + 0x18u) = MEM32(eax + 0xCu);
	MEM32(ecx + 0x14u) = MEM32(eax + 0x10u);
	eax = 1u;
	return eax;
}

