/* Returns 1 when the position at ecx lies outside the level bounds from LevelBoundsMin/LevelBoundsMax
   shrunk by the margin margin, and 0 otherwise. */
uint32_t PointIsOutsideLevelBounds(uint32_t position, uint32_t margin)
{
	uint32_t eax = 0;

	if (x87_round((double)LevelBoundsMin(0) + x87_float(margin)) > FLOAT_AT(position) || x87_round((double)LevelBoundsMax(0) - x87_float(margin)) < FLOAT_AT(position) || x87_round((double)LevelBoundsMin(1) + x87_float(margin)) > FLOAT_AT(position + 4u) || x87_round((double)LevelBoundsMax(1) - x87_float(margin)) < FLOAT_AT(position + 4u) || x87_round((double)LevelBoundsMin(2) + x87_float(margin)) > FLOAT_AT(position + 8u) || x87_round((double)LevelBoundsMax(2) - x87_float(margin)) < FLOAT_AT(position + 8u))
	{
		eax = 1u;
		return eax;
	}
	eax = 0u;
	return eax;
}

