/* walks the object's 16 blocks of 0x9C at +0xB4 and, for each non-empty block, shifts the two 10-entry
   handle lists at +0x24/+0x30 and -0x28/-0x34 left to drop zero entries with x86_rep_movs32. */
void ComponentSlotCompact(uint32_t component_handle)
{
	uint32_t eax = 0, ebp = 0, ebx = 0, edx = 0, handle = 0, ignored = 0, ignored_2 = 0;
	uint32_t stack = 0;
	uint32_t t1 = 0;

	if (component_handle != GameObjectLastHandle)
	{
		handle = component_handle;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	ebp = 0u;
	if (eax == 0u)
		return;
	ebx = eax + 0xB4u;
	stack = 0x10u;
	do
	{
		if (MEM32(ebx - 0x6Cu) != ebp)
		{
			eax = 0u;
			edx = ebx;
			do
			{
				if (MEM32(edx) == ebp)
				{
					if ((int32_t)eax < 0xA)
						x86_rep_movs32(edx, edx + 4u, 0xAu - eax);
					MEM32(ebx + 0x24u) = ebp;
				}
				edx += 4u;
				eax++;
			} while ((int32_t)eax < 0xA);
			eax = 0u;
			edx = ebx - 0x28u;
			do
			{
				if (MEM32(edx) == ebp)
				{
					if ((int32_t)eax < 0xA)
						x86_rep_movs32(edx, edx + 4u, 0xAu - eax);
					MEM32(ebx - 4u) = ebp;
				}
				edx += 4u;
				eax++;
			} while ((int32_t)eax < 0xA);
		}
		t1 = stack;
		ebx += 0x9Cu;
		stack = t1 - 1u;
	} while (t1 != 1u);
}

/* clears ComponentFamily_VA, sets its name to ComponentText_VA with version 3 and type_count 1, calls
   ObjectGroupComponent_Register, and registers it with GameObjectRegisterFamily(7, ComponentFamily_VA). */
