/* From the size triple at +0x1C/+0x20/+0x24, halves each value and writes the negated half extents at
   +0/+4/+8 and the positive half extents at +0xC/+0x10/+0x14, forming the box corners. */
void BoundsSetFromSize(uint32_t bounds)
{
	uint32_t eax = 0, ecx = 0, edi = 0, esi = 0;
	uint32_t saved_edi = 0, saved_eax = 0, saved_esi = 0, stack = 0;
	double f0 = 0;

	stack = bounds;
	ecx = stack;
	if (ecx != 0u)
	{
		eax = MEM32(ecx + 0x1Cu);
		esi = eax - ((int32_t)eax >> 31);
		eax = MEM32(ecx + 0x20u);
		edi = eax - ((int32_t)eax >> 31);
		eax = MEM32(ecx + 0x24u);
		esi = (int32_t)esi >> 1;
		saved_esi = esi;
		eax = (int32_t)(eax - ((int32_t)eax >> 31)) >> 1;
		stack = 0u - esi;
		saved_eax = eax;
		f0 = (double)(int32_t)stack;
		edi = (int32_t)edi >> 1;
		stack = 0u - eax;
		saved_edi = edi;
		MEMF(ecx) = (float)f0;
		f0 = (double)(int32_t)stack;
		stack = 0u - edi;
		MEMF(ecx + 4u) = (float)f0;
		MEMF(ecx + 8u) = (float)(double)(int32_t)stack;
		MEMF(ecx + 0xCu) = (float)(double)(int32_t)saved_esi;
		MEMF(ecx + 0x10u) = (float)(double)(int32_t)saved_eax;
		MEMF(ecx + 0x14u) = (float)(double)(int32_t)saved_edi;
	}
}

