/* The BoxVolumeNode type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t BoxVolumeNode_StateMachine(uint32_t ebp, uint32_t esi, uint32_t edi, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data, uint32_t time)
{
	uint32_t arg0 = 0, arg1 = 0, arg2 = 0, arg3 = 0, data_2 = 0, data_3 = 0, eax = 0, ebx = 0, ecx = 0, edx = 0, ignored = 0, ignored_2 = 0, node = 0, node_2 = 0, node_handle = 0;
	uint32_t saved_object = 0;

	saved_object = object;
	ecx = entry;
	eax = message;
	edx = MEM32(eax + 4u);
	ebx = MEM32(ecx);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax == 0xFFF9u)
	{
		node_2 = object;
		data_2 = data;
		BoxVolumeNodeStart(data_2, ebx, ebp, node_2, edi);
		eax = 1u;
		return eax;
	}
	if (eax == 0xFFFEu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0x2AF8u)
	{
		if (eax == 0x2AF9u)
		{
			eax = 1u;
			return eax;
		}
		if (eax != 0xFFFAu)
		{
			eax = 0u;
			return eax;
		}
		node_handle = ebx;
		NodeDestroySubtree(node_handle, &ignored, &ignored_2);
		eax = saved_object;
		MEM32(eax + 0x100u) = 0u;
		MEM32(eax + 0xFCu) = 0u;
		eax = 1u;
		return eax;
	}
	node = object;
	data_3 = data;
	arg3 = edx;
	arg2 = time;
	arg1 = ebx;
	arg0 = ecx;
	BoxVolumeNodeDraw(node, ebx, ebp, esi, data_3, arg0, arg1, arg2, arg3);
	eax = 1u;
	return eax;
}

/* Registers the BoxVolumeNode type (Node 20), a box in its own frame, 50 a side at first, with a
   PointNode at two of its corners, "Point1 - Width" and "Point2 - Breadth", which resize it when moved;
   drawn as red lines. No level places one and nothing makes one: fills its GameObjectType and stores it
   in its family. */
void BoxVolumeNode_Register(uint32_t family)
{
	GameObjectType_load(BoxVolumeNodeType_VA) = 0u;
	GameObjectType_flags(BoxVolumeNodeType_VA) = 0u;
	GameObjectType_size(BoxVolumeNodeType_VA) = 0x10Cu;
	GameObjectType_startup(BoxVolumeNodeType_VA) = 0x59010u;
	GameObjectType_shutdown(BoxVolumeNodeType_VA) = 0x59010u;
	GameObjectType_state_machine(BoxVolumeNodeType_VA) = 0xDB330u;
	GameObjectType_collect(BoxVolumeNodeType_VA) = 0x385E0u;
	GameObjectType_version(BoxVolumeNodeType_VA) = 1u;
	MEM32(family + 0x60u) = BoxVolumeNodeType_VA;
}

/* A corner point of a box moved: with the box's +0x104 set the box takes a new size from where the point
   is (its width from point 0, its breadth from point 1) and is centred again (BoundsSetFromSize); else
   the box itself moves so that its corner is at the point. */
void BoxVolumeNodeCornerMoved(uint32_t box_handle, uint32_t point_handle, uint32_t corner)
{
	uint32_t a = 0, b = 0, bounds = 0, eax = 0, ecx = 0, esi = 0, handle = 0, ignored = 0, ignored_2 = 0, out = 0;
	uint32_t saved_corner = 0, saved_point_handle = 0;
	uint32_t t1 = 0;
	double f0 = 0;

	saved_point_handle = point_handle;
	saved_corner = corner;
	eax = box_handle;
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
		esi = eax;
	}
	else
		esi = GameObjectLastObject;
	eax = saved_point_handle;
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	if (eax == 0u || esi == 0u)
		return;
	t1 = MEM32(esi + 0x104u);
	ecx = saved_corner;
	if (t1 == 0u)
	{
		eax += 0x7Cu;
		if (ecx == 0u)
		{
			b = esi + 0x7Cu;
			a = esi + 0xD0u;
			out = eax;
			VectorAdd(out, a, b);
			return;
		}
		b = esi + 0x7Cu;
		a = esi + 0xDCu;
		out = eax;
		VectorAdd(out, a, b);
		return;
	}
	if (ecx != 0u)
		MEMF(esi + 0xE4u) = (float)x87_round(FLOAT_AT(eax + 0x84u) - FLOAT_AT(esi + 0x84u));
	else
		MEMF(esi + 0xD0u) = (float)x87_round(FLOAT_AT(eax + 0x7Cu) - FLOAT_AT(esi + 0x7Cu));
	f0 = x87_round(FLOAT_AT(esi + 0xE0u) - FLOAT_AT(esi + 0xD4u));
	MEM32(esi + 0xECu) = x87_ftol(x87_round(FLOAT_AT(esi + 0xDCu) - FLOAT_AT(esi + 0xD0u)));
	eax = x87_ftol(f0);
	f0 = x87_round(FLOAT_AT(esi + 0xE4u) - FLOAT_AT(esi + 0xD8u));
	MEM32(esi + 0xF4u) = eax;
	bounds = esi + 0xD0u;
	MEM32(esi + 0xF0u) = x87_ftol(f0);
	BoundsSetFromSize(bounds);
}

