/* Resolves the game object from the theme action's target handle at ebx+0x48, finds its component with
   EntityGetAI, applies the action's value at ebx+0x50 through AISetTheme (over all 100 slots when the
   handle points to a group, then TargetListRequestRebuild), and marks ebx+0x40 done. */
void AISetThemeActionApply(uint32_t ebx)
{
	uint32_t ai = 0, eax = 0, ecx = 0, edi = 0, entity = 0, esi = 0, handle = 0, ignored = 0, ignored_2 = 0, node_handle = 0, theme_number = 0;

	if (MEM32(ebx + 0x40u) != 0u)
		return;
	esi = MEM32(ebx + 0x48u);
	if ((esi & 0x3F800u) == 0x800u)
	{
		node_handle = esi;
		PlayerStandInEntityNodeGetObject(node_handle, &eax, &ignored);
		esi = eax;
	}
	if ((esi & 0x7C0000u) != 0x80000u)
	{
		eax = MEM32(ebx + 0x48u);
		if ((eax & 0x7C0000u) != 0x2C0000u || (eax & 0x3F800u) != 0x7800u)
			return;
		node_handle = eax;
		eax = NodeGetOwnPart(node_handle);
		if (eax == 0u)
		{
			MEM32(ebx + 0x40u) = 1u;
			return;
		}
		edi = 0u;
		esi = eax + 0x18u;
		do
		{
			if (MEM32(esi + 0x194u) != 0u)
			{
				eax = MEM32(esi);
				if (eax != GameObjectLastHandle)
				{
					handle = eax;
					GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
				}
				else
					eax = GameObjectLastObject;
				if (eax != 0u)
				{
					entity = eax;
					eax = EntityGetAI(entity);
					if (eax == 0u)
						return;
					ecx = MEM32(ebx + 0x50u);
					if ((int32_t)ecx >= 0)
					{
						theme_number = ecx;
						ai = eax;
						AISetTheme(ai, theme_number);
					}
				}
			}
			edi++;
			esi += 4u;
		} while ((int32_t)edi < 0x64);
		TargetListRequestRebuild();
		MEM32(ebx + 0x40u) = 1u;
		return;
	}
	if (esi != GameObjectLastHandle)
	{
		handle = esi;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
	}
	else
		eax = GameObjectLastObject;
	if (eax == 0u)
	{
		MEM32(ebx + 0x40u) = 1u;
		return;
	}
	entity = eax;
	eax = EntityGetAI(entity);
	if (eax == 0u)
		return;
	ecx = MEM32(ebx + 0x50u);
	if ((int32_t)ecx < 0)
	{
		MEM32(ebx + 0x40u) = 1u;
		return;
	}
	theme_number = ecx;
	ai = eax;
	AISetTheme(ai, theme_number);
	TargetListRequestRebuild();
	MEM32(ebx + 0x40u) = 1u;
}

