/* The OrientSpawnAction type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t OrientSpawnAction_StateMachine(uint32_t ebx, uint32_t ebp, uint32_t entry, uint32_t object, uint32_t state, uint32_t message)
{
	uint32_t action = 0, eax = 0, ecx = 0, edi = 0, esi = 0;

	ecx = entry;
	eax = message;
	esi = MEM32(eax + 4u);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax == 0xFFF9u)
	{
		action = object;
		entry = ecx;
		OrientSpawnActionInit(action, entry);
		eax = 1u;
		return eax;
	}
	if (eax == 0xFFFEu)
	{
		eax = 1u;
		return eax;
	}
	if (eax == 0x2328u)
	{
		edi = object;
		OrientSpawnActionSpawn(ebx, ebp, esi, edi);
		eax = 1u;
		return eax;
	}
	if (eax == 0x2329u || eax == 0xFFFAu)
	{
		eax = 1u;
		return eax;
	}
	eax = 0u;
	return eax;
}

