/* Resolves the game object the state references (a path or a single handle) with
   NodeGetOwnPart/GameObjectFromHandle and toggles the enabled flag of it and, for a path, each of its
   up-to-100 objects with EntitySetAIEnabled. */
uint32_t AIEnabledActionToggleObjectsEnabled(uint32_t action, uint32_t ebp)
{
	uint32_t eax = 0, ebp_2 = 0, edi = 0, enabled = 0, entity = 0, esi = 0, handle = 0, ignored = 0, ignored_2 = 0, node_handle = 0;

	eax = MEM32(action + 0x40u);
	if (eax != 0u)
		return eax;
	eax = MEM32(action + 0x4Cu);
	if (eax == 0u)
		return eax;
	if ((eax & 0x7C0000u) != 0x80000u)
	{
		eax = MEM32(action + 0x48u);
		if ((eax & 0x7C0000u) != 0x2C0000u || (eax & 0x3F800u) != 0x7800u)
			return eax;
		node_handle = eax;
		eax = NodeGetOwnPart(node_handle);
		if (eax == 0u)
		{
			MEM32(action + 0x40u) = 1u;
			return eax;
		}
		ebp_2 = 0u;
		edi = eax + 0x18u;
		do
		{
			eax = MEM32(edi + 0x194u);
			if (eax != 0u)
			{
				eax = MEM32(edi);
				if (eax != GameObjectLastHandle)
				{
					handle = eax;
					GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
					esi = eax;
				}
				else
					esi = GameObjectLastObject;
				if (esi != 0u)
				{
					entity = esi;
					eax = EntityGetAI(entity);
					if (eax == 0u)
						return eax;
					enabled = ~MEM32(eax) & 1u;
					entity = esi;
					EntitySetAIEnabled(entity, enabled, &eax, &action, &ebp_2);
				}
			}
			ebp_2++;
			edi += 4u;
		} while ((int32_t)ebp_2 < 0x64);
		MEM32(action + 0x40u) = 1u;
		return eax;
	}
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &eax, &ignored, &ignored_2);
		esi = eax;
	}
	else
		esi = GameObjectLastObject;
	if (esi == 0u)
	{
		MEM32(action + 0x40u) = 1u;
		return eax;
	}
	entity = esi;
	eax = EntityGetAI(entity);
	if (eax == 0u)
		return eax;
	enabled = ~MEM32(eax) & 1u;
	entity = esi;
	EntitySetAIEnabled(entity, enabled, &eax, &action, &ebp);
	MEM32(action + 0x40u) = 1u;
	return eax;
}

/* When the action's +0x40 flag is set and +0x48 is non-zero, takes the game object from EntityGetAI(0)
   and calls EntitySetAIEnabled with the inverse of its enabled bit, then clears +0x40. */
uint32_t AIEnabledActionToggleObjectEnabled(uint32_t ebx, uint32_t ebp, uint32_t action)
{
	uint32_t eax = 0, enabled = 0, entity = 0;

	eax = MEM32(action + 0x40u);
	if (eax != 0u)
	{
		eax = MEM32(action + 0x48u);
		if (eax != 0u)
		{
			entity = 0u;
			eax = EntityGetAI(entity);
			if (eax != 0u)
			{
				enabled = ~MEM32(eax) & 1u;
				entity = 0u;
				EntitySetAIEnabled(entity, enabled, &eax, &ebx, &ebp);
				MEM32(action + 0x40u) = 0u;
			}
		}
	}
	return eax;
}

/* The AIEnabledAction type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t AIEnabledAction_StateMachine(uint32_t ebx, uint32_t ebp, uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data)
{
	uint32_t action = 0, action_2 = 0, action_handle = 0, eax = 0, ecx = 0, edx = 0, node = 0;

	ecx = entry;
	eax = message;
	edx = MEM32(ecx);
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(eax);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax == 0xF009u)
		{
			node = data;
			action_handle = edx;
			ActionRetarget(action_handle, node);
			eax = 1u;
			return eax;
		}
		if (eax == 0x2328u)
		{
			action = object;
			AIEnabledActionToggleObjectsEnabled(action, ebp);
			eax = 1u;
			return eax;
		}
		if (eax == 0x2329u)
		{
			action_2 = object;
			AIEnabledActionToggleObjectEnabled(ebx, ebp, action_2);
			eax = 1u;
			return eax;
		}
		if (eax != 0xFFFAu)
		{
			eax = 0u;
			return eax;
		}
		eax = 1u;
		return eax;
	}
	eax = object;
	edx = eax;
	MEM32(edx) = MEM32(AIEnabledActionNameText_VA);
	MEM32(edx + 4u) = MEM32(AIEnabledActionNameText_VA + 0x4u);
	MEM16(edx + 8u) = MEM16(AIEnabledActionNameText_VA + 0x8u);
	MEM8(edx + 0xAu) = MEM8(AIEnabledActionNameText_VA + 0xAu);
	MEM32(eax + 0x48u) = 0u;
	MEM32(eax + 0x4Cu) = 0u;
	MEM32(eax + 0x40u) = 0u;
	MEM32(ecx + 0x18u) = 0xFFFFFFFFu;
	eax = 1u;
	return eax;
}

