	do
	{
		t1 = MEM32(object + 0x20u);
		eax = t1;
		if (t1 == 0u || eax == 1u)
		{
			arg2_2 = edi;
			arg1_2 = object;
			arg0 = ebp;
			MissileLauncherCreateMissiles(arg0, arg1_2, arg2_2, &ebx, &ebp, &object, &edi);
		}
		edi++;
	} while ((int32_t)edi < (int32_t)MEM32(ebx + 0xCu));
	MEM32(object + 0x10u) = saved_arg2;
	MEM32(ebx + 0x38u) = 1u;
