/* probably creates a steering instance: it copies the fields of the source at edi into esi, zeroes
   esi+0x1C and esi+0x20, and stores LandingSteeringUpdate as the instance's update callback at entry+8. */
void LandingSteeringInit(uint32_t object, uint32_t data, uint32_t entry)
{
	uint32_t eax = 0, handle = 0, ignored = 0, ignored_2 = 0, ignored_3 = 0;
	uint32_t saved_entry = 0;

	saved_entry = entry;
	eax = MEM32(data);
	if (eax != GameObjectLastHandle)
	{
		handle = eax;
		GameObjectFromHandle(handle, &ignored, &ignored_2, &ignored_3);
	}
	MEM32(object) = MEM32(data);
	MEM32(object + 4u) = MEM32(data + 4u);
	MEM32(object + 8u) = MEM32(data + 8u);
	MEM32(object + 0xCu) = MEM32(data + 0xCu);
	MEM32(object + 0x10u) = MEM32(data + 0x10u);
	MEM32(object + 0x14u) = MEM32(data + 0x14u);
	MEM32(object + 0x18u) = MEM32(data + 0x18u);
	MEM32(object + 0x1Cu) = 0u;
	MEM32(object + 0x20u) = 0u;
	MEM32(saved_entry + 8u) = 0xF5700u;
}

/* The LandingSteering type's state machine: how its objects answer each message in each state
   (GameObjectDeliver). Hands back whether one was answered. */
uint32_t LandingSteering_StateMachine(uint32_t entry, uint32_t object, uint32_t state, uint32_t message, uint32_t data)
{
	uint32_t data_2 = 0, eax = 0, ecx = 0, object_2 = 0, slot = 0;

	ecx = entry;
	if (state != 0x7FFFu)
	{
		eax = 0u;
		return eax;
	}
	eax = MEM32(message);
	if (eax == 0xFFFFu)
	{
		eax = 1u;
		return eax;
	}
	if (eax != 0xFFF9u)
	{
		if (eax == 0xFFFEu)
		{
			eax = 1u;
			return eax;
		}
		if (eax != 0xFFFAu)
		{
			eax = 0u;
			return eax;
		}
		MEM32(ecx + 8u) = 0u;
		slot = 0u;
		SteeringClearEntitySlot(object, slot);
		eax = 1u;
		return eax;
	}
	object_2 = object;
	data_2 = data;
	entry = ecx;
	LandingSteeringInit(object_2, data_2, entry);
	eax = 1u;
	return eax;
}

/* Registers the LandingSteering type (Steering 16), made by LandingSteeringReplace (0xF55A0, 0x1C
   bytes), which only four ships call after picking their nearest object: ZenReEntryPod, ZenReconShip,
   ZenShuttle, SeaSergeant. "Landing" is the main session's reading of what they pick; by its functions'
   descriptions (not read line by line) it steers to its point and destroys itself once there and slower
   than 2 (LandingSteeringCheckTargetReached, LandingSteeringUpdate): fills its GameObjectType and stores
   it in its family. */
void LandingSteering_Register(uint32_t family)
{
	GameObjectType_startup(LandingSteeringType_VA) = 0u;
	GameObjectType_shutdown(LandingSteeringType_VA) = 0u;
	GameObjectType_load(LandingSteeringType_VA) = 0u;
	GameObjectType_collect(LandingSteeringType_VA) = 0u;
	GameObjectType_version(LandingSteeringType_VA) = 0u;
	GameObjectType_flags(LandingSteeringType_VA) = 0u;
	GameObjectType_size(LandingSteeringType_VA) = 0x24u;
	GameObjectType_state_machine(LandingSteeringType_VA) = 0xF5A10u;
	MEM32(family + 0x50u) = LandingSteeringType_VA;
}

