			eax = t1;
			f0 = x87_round(f0 + x87_round(x87_float(stack_200000) * FLOAT_AT(ecx + eax * 4u + 4u)));
			stack_8 = float_to_bits((float)x87_round(x87_float(stack_8) + x87_float(stack_200000)));
			stack_200000 = float_to_bits((float)x87_round(x87_float(stack) * x87_float(stack_200000)));
			if ((int32_t)t1 < 0)
				eax = esi;
			t2 = eax - 1u;
			eax = t2;
			f0 = x87_round(f0 + x87_round(x87_float(stack_200000) * FLOAT_AT(ecx + eax * 4u + 4u)));
			stack_8 = float_to_bits((float)x87_round(x87_float(stack_8) + x87_float(stack_200000)));
			stack_200000 = float_to_bits((float)x87_round(x87_float(stack) * x87_float(stack_200000)));
			if ((int32_t)t2 < 0)
				eax = esi;
			t3 = eax - 1u;
			eax = t3;
			f0 = x87_round(f0 + x87_round(x87_float(stack_200000) * FLOAT_AT(ecx + eax * 4u + 4u)));
			stack_8 = float_to_bits((float)x87_round(x87_float(stack_8) + x87_float(stack_200000)));
			stack_200000 = float_to_bits((float)x87_round(x87_float(stack) * x87_float(stack_200000)));
			if ((int32_t)t3 < 0)
				eax = esi;
			edi += 4u;
			f1 = x87_round(x87_float(stack_200000) * FLOAT_AT(ecx + eax * 4u));
			eax--;
			ebx += 4u;
			f0 = x87_round(f0 + f1);
			f1 = x87_round(x87_float(stack_8) + x87_float(stack_200000));
			stack_8 = float_to_bits((float)f1);
			stack_200000 = float_to_bits((float)x87_round(x87_float(stack) * x87_float(stack_200000)));
