		arg2 = saved_effect;
		x86_call(vcSceneObjectGetTransform_entry, 0x0010B6DCu, 3, arg0, arg1, arg2);
		arg2 = effect;
		arg1 = edi;
		arg0 = MEM32(effect + 0x5Cu);
