		arg2 = 0u;
		arg1 = MEM32(effect + 0x50u);
		arg0 = MEM32(effect + 0x5Cu);
		x86_call(vcSceneObjectAttach_entry, 0x0010B6F6u, 3, arg0, arg1, arg2);
		arg2 = 4u;
		arg1 = 0u;
