		ignored = g_eax;
		edx = g_edx;
		arg0 = MEM32(effect + 0x5Cu);
		ebx = EffectObjectStop(edx, ebx, ebp, arg0);
		arg1 = 0u;
		arg0 = MEM32(effect + 0x5Cu);
		ObjectSetPaused(arg0, arg1);
		ecx = MEM32(ebx + 0x10u) | 1u;
		MEM16(ebx + 0xEu) = 1u;
