	arg2 = 0xFFFFFFFFu;
	arg1 = 0u;
	arg0 = MEM32(object + 0x5Cu);
	x86_call(vcSceneObjectAttach_entry, 0x0010B8A6u, 3, arg0, arg1, arg2);
	arg0 = MEM32(object + 0x5Cu);
	EffectObjectActivate(arg0);
	MEM32(entry + 0x18u) = MEM32(esi + 0x114u) + MEM32(esi + 0x110u);
