	MEMF(edx + 0x24u) = (float)x87_round(x87_round(x87_round(x87_round(FLOAT_AT(ecx + 0x14u) * FLOAT_AT(eax + 0x18u)) + x87_round(FLOAT_AT(eax + 0x28u) * FLOAT_AT(ecx + 0x18u))) + x87_round(FLOAT_AT(eax + 0x38u) * FLOAT_AT(ecx + 0x1Cu))) + x87_round(FLOAT_AT(ecx + 0x10u) * FLOAT_AT(eax + 8u)));
