	MEMF(edx + 8u) = (float)x87_round(x87_round(x87_round(x87_round(FLOAT_AT(ecx + 0x24u) * FLOAT_AT(eax + 0x10u)) + x87_round(FLOAT_AT(eax + 0x20u) * FLOAT_AT(ecx + 0x28u))) + x87_round(FLOAT_AT(ecx + 0x2Cu) * FLOAT_AT(eax + 0x30u))) + x87_round(FLOAT_AT(ecx + 0x20u) * FLOAT_AT(eax)));
	MEMF(edx + 0x18u) = (float)x87_round(x87_round(x87_round(x87_round(FLOAT_AT(ecx + 0x20u) * FLOAT_AT(eax + 4u)) + x87_round(FLOAT_AT(eax + 0x14u) * FLOAT_AT(ecx + 0x24u))) + x87_round(FLOAT_AT(eax + 0x34u) * FLOAT_AT(ecx + 0x2Cu))) + x87_round(FLOAT_AT(eax + 0x24u) * FLOAT_AT(ecx + 0x28u)));
