	MEMF(edx + 0x38u) = (float)x87_round(x87_round(x87_round(x87_round(FLOAT_AT(ecx + 0x20u) * FLOAT_AT(eax + 0xCu)) + x87_round(FLOAT_AT(ecx + 0x2Cu) * FLOAT_AT(eax + 0x3Cu))) + x87_round(FLOAT_AT(ecx + 0x28u) * FLOAT_AT(eax + 0x2Cu))) + x87_round(FLOAT_AT(ecx + 0x24u) * FLOAT_AT(eax + 0x1Cu)));
	MEMF(edx + 0xCu) = (float)x87_round(x87_round(x87_round(x87_round(FLOAT_AT(ecx + 0x34u) * FLOAT_AT(eax + 0x10u)) + x87_round(FLOAT_AT(eax + 0x20u) * FLOAT_AT(ecx + 0x38u))) + x87_round(FLOAT_AT(ecx + 0x3Cu) * FLOAT_AT(eax + 0x30u))) + x87_round(FLOAT_AT(ecx + 0x30u) * FLOAT_AT(eax)));
