	ebp = 1u;
	if (FLOAT_AT(esi + ecx * 4u) < FLOAT_AT(ebx + ecx * 4u))
	{
		eax = MEM32(ebx + ecx * 4u);
		ebp = 0u;
		MEM32(edx + ecx * 4u) = eax;
		if (FLOAT_AT(esi + edi * 4u) < FLOAT_AT(ebx + edi * 4u))
		{
			eax = 0u;
			MEM32(edx + edi * 4u) = MEM32(ebx + edi * 4u);
			return eax;
		}
		ecx_2 = arg0;
		if (!(FLOAT_AT(esi + edi * 4u) > FLOAT_AT(ecx_2 + edi * 4u)))
		{
			eax = ebp;
			return eax;
		}
		eax = 0u;
		MEM32(edx + edi * 4u) = MEM32(ecx_2 + edi * 4u);
		return eax;
	}
	if (FLOAT_AT(esi + ecx * 4u) > FLOAT_AT(arg0 + ecx * 4u))
	{
		eax = MEM32(arg0 + ecx * 4u);
		ebp = 0u;
		MEM32(edx + ecx * 4u) = eax;
	}
	if (FLOAT_AT(esi + edi * 4u) < FLOAT_AT(ebx + edi * 4u))
	{
		eax = 0u;
		MEM32(edx + edi * 4u) = MEM32(ebx + edi * 4u);
		return eax;
	}
	ecx_2 = arg0;
	if (!(FLOAT_AT(esi + edi * 4u) > FLOAT_AT(ecx_2 + edi * 4u)))
	{
		eax = ebp;
		return eax;
	}
	eax = 0u;
	MEM32(edx + edi * 4u) = MEM32(ecx_2 + edi * 4u);
	return eax;
