					f1 = x87_round(FLOAT_AT(ebx + 4u) - FLOAT_AT(ecx + 4u));
					f2 = x87_round(FLOAT_AT(ebx + 8u) - FLOAT_AT(ecx + 8u));
					stack = float_to_bits((float)x87_round(sqrt(x87_round(x87_round(f0 * f0) + x87_round(x87_round(f1 * f1) + x87_round(f2 * f2))))));
					ebx = stack_200000;
