				arg3 = esi;
				arg2 = stack_C;
				arg1 = esi + 0x24u;
				arg0_2 = edx;
				g_edx = edx;
				x86_call(vcQuadtreeInsert, 0x00119DAFu, 4, arg0_2, arg1, arg2, arg3);
