			ignored = g_ecx;
			edx = g_edx;
			MEM32(esi + 0x130u) = eax;
			arg1_2 = 0xCu;
			arg0_2 = MEM32(edi + 0x6Cu);
			g_edx = edx;
			x86_call(crt_calloc, 0x00141581u, 2, arg0_2, arg1_2);
